DROP TABLE IF EXISTS `envio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `envio` (
  `idEnvio` int NOT NULL AUTO_INCREMENT,
  `guia` varchar(30) NOT NULL,
  `idCliente` int NOT NULL,
  `idSucursal` int NOT NULL,
  `idEstadoEnvio` int DEFAULT NULL,
  `costo` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`idEnvio`),
  UNIQUE KEY `guia` (`guia`),
  KEY `idEstadoEnvio` (`idEstadoEnvio`),
  KEY `idCliente` (`idCliente`),
  KEY `idSucursal` (`idSucursal`),
  CONSTRAINT `envio_ibfk_1` FOREIGN KEY (`idEstadoEnvio`) REFERENCES `estadoenvio` (`idEstadoenvio`),
  CONSTRAINT `envio_ibfk_2` FOREIGN KEY (`idCliente`) REFERENCES `cliente` (`idCliente`),
  CONSTRAINT `envio_ibfk_3` FOREIGN KEY (`idSucursal`) REFERENCES `sucursal` (`idSucursal`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
